do $$
declare base text; n_new int; n_carried int; missing text; ident text;
begin
  if exists (select 1 from public.catalog_file_commercial where manufacturer = 'ohio-medical' and identity_sha256 = 'c96083fbcd3a66533a49b2e037d3a686150d88ed659e87a92242df0818a49290') then
